.filters button[aria-pressed=true] { background: #10110d; color: white; }
.startup { max-width: 480px; margin: 10vh auto; padding: 24px; }
.startup h1 { margin-bottom: 16px; }
.backdrop { position: fixed; inset: 0; z-index: 10; background: #17171355; display: flex; justify-content: flex-end; padding: 24px; }
.panel { background: white; border: 1px solid #e1dcd1; border-radius: 20px; width: 440px; max-width: 100%; overflow-y: auto; overscroll-behavior: contain; padding: 20px; scroll-padding-block: 90px; }
.panelHeader { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; background: white; }
.panelHeader h2 { font-size: 22px; }
