.hero p { color: #625f55; font-size: 11px; }
.hero strong { display: block; color: #161713; font: 700 24px/1.2 JournalCondensed, sans-serif; font-variant-numeric: tabular-nums; }
.recorded { padding: 12px; border-radius: 10px; background: #f4f1eb; margin: 8px 0; }
.install { font-size: 12px; color: #625f55; }
@media (max-width: 1023px) {
  .shell { display: block; background: #f4f1eb; }
  .shell nav { position: fixed; bottom: 0; left: 0; right: 0; z-index: 2; flex-direction: row; justify-content: space-around; gap: 4px; padding: 6px max(8px, env(safe-area-inset-right)) max(6px, env(safe-area-inset-bottom)); border-top: 1px solid #e1dcd1; border-right: 0; background: white; }
  .shell nav strong { display: none; }
  .shell nav button { min-width: 0; flex: 1; text-align: center; font-size: 10px; padding: 4px 2px; line-height: 1.2; }
    .shell nav button:nth-of-type(2) { margin: 0; border: 0; }
  .shell main { padding: 24px 16px 110px; max-width: 480px; }
  .backdrop { padding: 24px 0 0; align-items: flex-end; }
  .panel { width: 100%; max-width: none; max-height: calc(100dvh - 24px); border-radius: 20px 20px 0 0; min-height: calc(100dvh - 24px); padding: 20px 20px max(20px, env(safe-area-inset-bottom)); }
}
@media (max-width: 420px) {
  .hero { grid-template-columns: 1fr 1fr; }
  .fieldGrid { gap: 0 8px; }
}
.formFields { border: 0; padding: 0; margin: 0; }
.formFields > legend { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
.panel .actions p { width: 100%; font-size: 11px; margin: 0; color: #625f55; }
.actions button[type=submit] { color: white; background: #10110d; border-color: #10110d; }
.planForm .actions button:first-child:not([type=submit]) { color: #25251f; background: white; }
.planForm .actions button[type=submit] { flex: 1; }
.updateCheck { display: block; margin: -6px 0 12px auto; font-size: 11px; padding: 6px 10px; }

.navIcon { display: inline-block; width: 24px; font-size: 18px; line-height: 1; }
@media (max-width: 1023px) { .navIcon { display: block; width: auto; margin-bottom: 4px; } }

