    const d1 = await page.evaluate(() => window.d1Evidence.generate(24999)); expect(d1.counts.plans).toBe(25000);
    await page.addScriptTag({ path: '.cache/browser-generator/generator.js' });
    source = await page.evaluate(async () => {
